steps.solution:
#include <iostream>
using namespace std;

int main() {
    int temp;
    cin >> temp;

    while (temp < 50) {
        temp += 10;
        cout << "WARMING: " << temp << endl;
    }
    cout << "READY FOR FLIGHT" << endl;

    return 0;
}

