steps.solution:
#include <iostream>
using namespace std;

int main() {
    int voltage, target;
    cin >> voltage >> target;

    do {
        voltage += 25;
        cout << "PULSE: " << voltage << endl;
    } while (voltage < target);

    cout << "LIDAR CHARGED" << endl;

    return 0;
}

