steps.solution:
#include <iostream>
using namespace std;

int main() {
    int val;
    cin >> val;
    int sum = 0;

    while (val != -1) {
        sum += val;
        cin >> val;
    }

    cout << "TOTAL TELEMETRY: " << sum << endl;

    return 0;
}
